# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SON BASAMAKLARA DAYALI BÖLÜNEBİLME KURALLARI (2, 4, 5, 8, 10)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">BİRLER BASAMAĞINA BAKILANLAR (2, 5, 10)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• 10 = 2 · 5 olduğundan 10\'un katları 2, 5 ve 10\'a tam bölünür</text>\n  <text x="35" y="112" font-size="11.2" fill="#1e3a8a">• 2 ile bölünebilme: Birler basamağı çift (0, 2, 4, 6, 8) olmalı</text>\n  <text x="35" y="132" font-size="10.8" fill="#1e3a8a">  Tek sayıların 2 ile bölümünden kalan 1\'dir</text>\n  <text x="35" y="156" font-size="11.2" fill="#1e3a8a">• 5 ile bölünebilme: Birler basamağı 0 veya 5 olmalı</text>\n  <text x="35" y="180" font-size="11.2" fill="#1e3a8a">• 10 ile bölünebilme: Birler basamağı 0 olmalı (Kalan = birler b.)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">SON İKİ VE SON ÜÇ BASAMAĞA BAKILANLAR (4, 8)</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• 4 ile bölünebilme (100 = 4 · 25 tam bölünür):</text>\n  <text x="370" y="108" font-size="10.8" fill="#14532d">  Son iki basamağı (ab) 00 veya 4\'ün katı olmalıdır</text>\n  <text x="370" y="128" font-size="10.8" fill="#14532d">  4 ile bölümden kalan = Son iki basamağın 4\'e bölümünden kalan</text>\n  <text x="370" y="152" font-size="11.2" fill="#14532d">• 8 ile bölünebilme (1000 = 8 · 125 tam bölünür):</text>\n  <text x="370" y="172" font-size="10.8" fill="#14532d">  Son üç basamağı (abc) 000 veya 8\'in katı olmalıdır</text>\n  <text x="370" y="192" font-size="10.8" fill="#14532d">  8 ile bölümden kalan = Son üç basamağın 8\'e bölümünden kalan</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">10^k sayısı 2^k ve 5^k ile tam bölündüğünden, 2^k kuralında son k basamağa bakılır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">RAKAMLAR TOPLAMINA DAYALI BÖLÜNEBİLME (3 VE 9) VE KALAN CEBİRİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">3 VE 9 İLE BÖLÜNEBİLME MUHAKEMESİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#581c87">• Basamak Özelliği: 10^n = (99...9) + 1 = 9k + 1</text>\n  <text x="35" y="112" font-size="11.2" fill="#581c87">• abcd = 1000a + 100b + 10c + d = 9·(111a+11b+c) + (a+b+c+d)</text>\n  <text x="35" y="136" font-size="11.2" fill="#581c87">• 9 ile bölümden kalan = Rakamlar toplamının 9\'a bölümünden kalan</text>\n  <text x="35" y="160" font-size="11.2" fill="#581c87">• 3 ile bölümden kalan = Rakamlar toplamının 3\'e bölümünden kalan</text>\n  <text x="35" y="184" font-size="11.2" fill="#581c87">• 9\'a tam bölünen her doğal sayı 3\'e de tam bölünür</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">KALANLARLA İŞLEM YAPMA ÖZELLİĞİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#7c2d12">• A ve B sayılarının m ile bölümünden kalanlar k1 ve k2 ise:</text>\n  <text x="370" y="112" font-size="11.2" fill="#7c2d12">• (A + B)\'nin m ile bölümünden kalan ↔ (k1 + k2)\'nin kalanı</text>\n  <text x="370" y="136" font-size="11.2" fill="#7c2d12">• (A · B)\'nin m ile bölümünden kalan ↔ (k1 · k2)\'nin kalanı</text>\n  <text x="370" y="160" font-size="11.2" fill="#7c2d12">• (A^n)\'nin m ile bölümünden kalan ↔ (k1^n)\'nin kalanı</text>\n  <text x="370" y="184" font-size="11.2" fill="#7c2d12">• Büyük sayıları çarpmak yerine kalanları çarpmak yeterlidir!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Bir doğal sayının basamaklarındaki rakamların yer değiştirmesi 3 ve 9 ile bölümünden kalanı değiştirmez.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ARALARINDA ASAL ÇARPANLARIN EKOK\'UNA BÖLÜNEBİLME (6, 12, 15, 36, 45)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">BİRLEŞİK SAYILARA BÖLÜNEBİLME İLKESİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#7f1d1d">• EBOB(a, b) = 1 (aralarında asal) ise EKOK(a, b) = a · b</text>\n  <text x="35" y="112" font-size="11.2" fill="#7f1d1d">• 6 ile bölünebilme  → Hem 2 hem 3 ile tam bölünmeli</text>\n  <text x="35" y="136" font-size="11.2" fill="#7f1d1d">• 12 ile bölünebilme → Hem 3 hem 4 ile tam bölünmeli</text>\n  <text x="35" y="160" font-size="11.2" fill="#7f1d1d">• 15 ile bölünebilme → Hem 3 hem 5 ile tam bölünmeli</text>\n  <text x="35" y="184" font-size="11.2" fill="#7f1d1d">• 36 → (4 ve 9)  |  45 → (5 ve 9)  |  90 → (9 ve 10)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#065f46">UYGULAMA SIRASI VE KALAN MUHAKEMESİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#064e3b">• 1. Adım: Önce SON BASAMAĞI ilgilendiren kural uygulanır</text>\n  <text x="370" y="108" font-size="10.8" fill="#064e3b">  (Örn: 36 için önce 4 kuralı, 45 için önce 5 kuralı)</text>\n  <text x="370" y="130" font-size="11.2" fill="#064e3b">• 2. Adım: Sonra RAKAMLAR TOPLAMI kuralı (3 veya 9) uygulanır</text>\n  <text x="370" y="154" font-size="11.2" fill="#064e3b">• Kalanlı sorularda: Sayının d = a·b ile bölümünden kalan k ise</text>\n  <text x="370" y="174" font-size="10.8" fill="#064e3b">  sayının a ve b ile bölümünden kalanlar, k\'nin kalanlarına eşittir!</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Dikkat: 12 için (2 ve 6) veya 36 için (6 ve 6) seçilmez; seçilen çarpanlar aralarında asal (EBOB=1) olmalıdır!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
